HERO_STR_STATIC(hero_str_27e90188, "`int` is not a word in this language \342\200\224 to make an integer out of a float, `to_i64` truncates toward zero and gives an `i64?` because the value may not fit: `to_i64(x).must()`. As a TYPE an integer says its width: `i64`, and also `i8` `i16` `i32` `u8` `u16` `u32` `u64`");
HERO_STR_STATIC(hero_str_213aac7a, "to_i64");
